import math

ROOT = Path(__file__).resolve().parents[1]
VERSION = '20260920-launch-1'
URL = 'https://rentsketch.com'
PAGES = []

def save(path, text):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text.strip() + '\n')

