def cta():
    return '''<section class="cta-band"><div class="wrap cta-inner"><div><h2>Let your customers see<br>what they’re planning.</h2><p>Try RentSketch for your rental business. 14 days, no credit card.</p></div><a class="btn lime" href="/business/signup.html">Start your free trial <span aria-hidden="true">↗</span></a></div></section>'''

def faq(items):
    return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'

def prices():
    data=[('starter','Starter',49,490,'For a rental business getting started with visual planning.',['Branded event designer','Catalog and rental prices','Customer designs and quote requests','Business dashboard']),('pro','Pro',99,990,'For businesses connecting designs to their booking workflow.',['Everything in Starter','Custom branding and colors','Deposit collection with Stripe setup','Order and integration workflows']),('commerce','Business',199,1990,'For teams coordinating a larger rental operation.',['Everything in Pro','Multiple staff accounts','Webhook integrations','Support for connected workflows'])]
    cards=''
    for key,name,monthly,annual,desc,features in data:
        cards+=f'''<article class="price-card {'featured' if key=='pro' else ''}" data-plan="{key}"><h3>{name}</h3><p class="desc">{desc}</p><div class="price"><span data-monthly="{monthly}" data-annual="{annual}">${monthly}</span><small data-period>/month</small></div><div class="price-sub" data-annual-note>${annual:,} billed yearly if you choose annual</div><ul>{''.join('<li>'+f+'</li>' for f in features)}</ul><a class="btn {'primary' if key=='pro' else ''}" href="/business/signup.html?plan={key}">Try {name} free <span aria-hidden="true">↗</span></a></article>'''
    return '''<div class="billing-toggle" role="group" aria-label="Billing interval"><button type="button" data-billing="monthly" aria-pressed="true">Monthly</button><button type="button" data-billing="annual" aria-pressed="false">Yearly · pay for 10 months</button></div><div class="price-grid">'''+cards+'''</div><p class="pricing-note">USD. 14-day trial. No credit card required. No automatic charge when the trial ends.<br>Business subscriptions renew until canceled. Stripe shows the amount before you pay.</p>'''

