page('business/index.html','Event Design Software for Rental Companies | RentSketch','Give rental customers a branded 2D and 3D designer on your website. Configure your catalog, review customer plans and manage quote requests in RentSketch.', '''<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">RentSketch for rental companies</div><h1>Your inventory.<br><span>Their event.<br>One clear picture.</span></h1><p class="lead">Help customers visualize the setup before your next quote. Bring your catalog, branding and customer layouts into a single planning workflow.</p><div class="actions"><a class="btn primary" href="/business/signup.html">Start a 14-day free trial ↗</a><a class="btn" href="/demo/">Explore the demo</a></div><p class="micro">No credit card. No automatic charge when the trial ends.</p></div>'''+studio()+'''</div></section><section class="section"><div class="wrap two-col"><div><div class="eyebrow">Built around your rental catalog</div><h2>Give every quote<br>a visual starting point.</h2><p>A request for “a tent for 80 people” leaves a lot to discuss. A layout helps you review tables, chairs, dancing and service areas together.</p><p>RentSketch organizes that conversation around the products and pricing you configure. Supported visual models give the design recognizable equipment rather than a blank diagram.</p></div><ul class="benefits"><li><strong>Products:</strong> add names, prices, dimensions and supported visuals.</li><li><strong>Branding:</strong> configure your name, logo and customer experience.</li><li><strong>Requests:</strong> review submitted customer designs and follow up.</li><li><strong>Installation:</strong> embed the designer on an approved website domain.</li><li><strong>Billing:</strong> manage your subscription in the business dashboard.</li></ul></div></section><section class="section tinted"><div class="wrap"><div class="section-heading"><div class="eyebrow">Your first workspace</div><h2>Know what comes next.</h2></div><div class="steps"><article class="step"><span class="number">01</span><h3>Build your catalog.</h3><p>Add the products you rent. Set prices, sizes and visuals in Products. Review the details before customers use the designer.</p></article><article class="step"><span class="number">02</span><h3>Make it yours.</h3><p>Configure Branding, open your customer designer and check an example layout. Confirm the catalog represents your business.</p></article><article class="step"><span class="number">03</span><h3>Install and share.</h3><p>Add your domain in Install and place the embed on your website. Customer quote requests arrive in Requests.</p></article></div><p class="support-line"><a href="/help/#business">Read the setup walkthrough →</a></p></div></section><section class="section"><div class="wrap faq-layout"><div><div class="eyebrow">An honest fit</div><h2>Visual planning for your existing operation.</h2><p>Keep your booking process. Add a clearer way to plan.</p></div>'''+faq([('Will it work with my equipment?','The catalog supports dimensions, pricing and mappings to the visual library. Check your required equipment during the free trial; a custom 3D model for every product is not automatically included.'),('Will it automatically sync my rental system?','There is no automatic connection to every rental system. Embedding works independently; supported integrations and webhook workflows require configuration.'),('Can I collect rental deposits?','Deposit workflows require the appropriate business configuration and Stripe onboarding. A RentSketch software subscription is separate from your customers’ equipment payments.'),('How much is a business subscription?','Current plans are Starter $49/month, Pro $99/month and Business $199/month. Annual options are $490, $990 and $1,990. <a href="/business/pricing.html">Compare plans</a>.')])+'''</div></section>'''+cta(),tour=True)

page('business/pricing.html','RentSketch Pricing | Business Plans & One-Time Event Pass','Compare RentSketch business plans from $49/month with a 14-day free trial, or a $9.99 Event Pass for one event. See annual pricing and renewal details.', '''<section class="page-hero"><div class="wrap"><div class="eyebrow">Clear plans. Two ways to get started.</div><h1>A business workspace.<br>Or just your next event.</h1><p>Choose a business trial for your rental company. Choose an Event Pass when you’re planning one event.</p></div></section><section class="section" id="business-plans"><div class="wrap">'''+prices()+'''<div class="event-pass" id="event-pass"><div><span class="pill">For individual event planners</span><h3 style="margin-top:13px">Event Pass · $9.99 once</h3><p>One event. 30 days to edit, save, print and share. A five-minute preview is free. Renew the same event for $4.99 for 30 more days, only when you choose. No recurring subscription. Equipment rentals are separate.</p></div><a class="btn primary" href="/designer/">Preview my event ↗</a></div></div></section><section class="section tinted"><div class="wrap faq-layout"><div><h2>Before you choose.</h2><p>Questions about the right fit?<br><a href="mailto:hello@rentsketch.com">Contact RentSketch</a>.</p></div>'''+faq([('Will the business trial charge me automatically?','No. You do not enter a card to start. After 14 days, choose and purchase a subscription in your dashboard to continue.'),('When does a paid business plan start?','The subscription begins when you complete Stripe Checkout. The billing interval and total are shown before you pay. Monthly or annual subscriptions renew until canceled.'),('Can I cancel a business subscription?','Use Billing → Manage Billing in Stripe in your dashboard to manage payment details, invoices and cancellation. Check the effective date displayed by Stripe.'),('Does the Event Pass include rental equipment?','No. The Event Pass pays for software access to one design. Equipment, delivery, installation and the rental order are separate.'),('I already have a confirmed Friendly Party Rental booking. Do I pay again?','An eligible active confirmed Friendly booking includes design access. Use the <a href="/my-event/?tenant=friendly&amp;mode=order">existing order login</a> with your first name and order number.'),('How do I get back to an event I paid for?','Payment returns you to the saved event. Your access email contains a private link, and <a href="/my-event/">Open my saved event</a> can send it again. Keep the private link safe.')])+'''</div></section>''')

page('business/signup.html','Start Your 14-Day Business Trial | RentSketch','Create a RentSketch rental business workspace. Try the branded event designer and dashboard for 14 days. No credit card or automatic charge.', '''<div class="wrap signup-layout"><div><div class="eyebrow">Your RentSketch business workspace</div><h1>Let’s put your rentals<br>in the picture.</h1><p>Start your 14-day trial. Set up your catalog, explore customer layouts and see how RentSketch fits your business.</p><ul class="benefits"><li>No credit card required</li><li>No automatic charge when the trial ends</li><li>Choose a paid subscription in Billing when you’re ready</li></ul><p class="support-line">Already have an account? <a href="/dashboard/">Log in →</a></p><p class="support-line">Planning one event? <a href="/business/pricing.html#event-pass">View the Event Pass →</a></p></div><div class="signup-box"><form id="business-signup"><h2>Create your workspace</h2><div class="field"><label for="businessName">Business name</label><input id="businessName" name="businessName" autocomplete="organization" required maxlength="120"></div><div class="field"><label for="contactEmail">Work email</label><input id="contactEmail" name="contactEmail" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="new-password" required minlength="8" maxlength="72" aria-describedby="password-hint"><span id="password-hint" class="micro">8–72 characters. Use a unique password.</span></div><fieldset class="plan-choices"><legend>Choose a plan to try</legend><label class="plan-choice"><input type="radio" name="plan" value="starter"><strong>Starter</strong><span>$49/month after trial</span></label><label class="plan-choice"><input type="radio" name="plan" value="pro" checked><strong>Pro</strong><span>$99/month after trial</span></label><label class="plan-choice"><input type="radio" name="plan" value="commerce"><strong>Business</strong><span>$199/month after trial</span></label></fieldset><p class="micro">Selecting a plan starts a free trial. It does not start a paid subscription.</p><div class="form-error" id="signup-error" role="alert" hidden></div><button class="btn primary" type="submit">Create my free workspace ↗</button><p class="micro" style="margin:15px 0 0">Your account and event data are handled as described in our <a href="/privacy/">privacy notice</a>.</p></form><div class="success-box" id="signup-success" hidden role="status"><h2>Your workspace is ready.</h2><p>No charge was made. Start by adding products, setting your branding and previewing your customer designer.</p><a class="btn primary" href="/dashboard/#/overview">Open my dashboard ↗</a></div></div></div><script src="/business/signup.js?v='''+VERSION+'''" defer></script>''',noindex=True)

articles = [
('tent-layout-software','Tent Layout Software for 2D & 3D Event Planning','Plan a tent layout with real dimensions, tables, chairs and a dance floor. Explore the same event in 2D and 3D with RentSketch.','Plan the tent.<br>Understand the space.', 'Turn a tent size into a layout you can discuss with your customer, venue and rental team.',[
('Start with the footprint, not just the guest count.','A guest count is a starting point. The arrangement of tables, service areas and a dance floor changes how the event uses a tent. Begin with the tent’s dimensions and style, then identify what has to fit inside. A pole tent also introduces interior poles that need to remain visible in the planning conversation.'),
('Build the event around the equipment.','Add the table types and chair arrangements you intend to use. Include the DJ, buffet, bar and other equipment before calling the plan complete. Reserve circulation space and review entrances instead of filling every available area with seating. RentSketch’s visual plan helps show those tradeoffs before setup day.'),
('Use 2D for arrangement and 3D for perspective.','The overhead view makes it easier to compare positions. The 3D view gives customers a different way to understand the same design. Review both when discussing what the event will look like. You can explore a furnished example without signing up on the product demo page.'),
('Review the real site before confirming the rental.','A diagram is a planning aid. Actual ground conditions, tent anchoring, exits and installation clearances must be checked with the rental team and venue. Manufacturer instructions and local requirements determine the installation; an attractive digital plan does not approve it.'),
('Bring the plan into the quote.','Rental businesses can configure products and prices, map supported visuals and review customer quote requests. Confirm availability and final service details in your rental workflow. Individual planners can purchase a separate Event Pass when they need to edit, save and share their own event.')]),
('tent-diagram-software','Tent Diagram Software | Clear Event & Seating Plans','Create visual tent diagrams with tables, chairs and event equipment. Review overhead layouts and 3D views before discussing the final setup with your rental team.','Make the tent diagram<br>easy to understand.','Create a shared reference for the equipment, the arrangement and the questions still to resolve.',[
('What a useful tent diagram includes.','Start with the tent’s size and style. Add each table, the intended seating and the equipment that occupies floor space. A dance floor, beverage station or service table belongs in the first draft, because adding it later can change the entire seating arrangement.'),
('Show the space between the objects.','The blank parts of a diagram matter. People need routes from the entrance to their seats and to service areas. Keep central poles and other obstructions visible. Share the drawing with the rental team so they can review clearances and the actual installation conditions.'),
('Compare the overhead plan with a 3D view.','An overhead diagram is useful for placement, but many customers find a perspective view easier to understand. RentSketch lets you see the same event in both. The product demo shows how the relationship between tables, seating and the tent changes from another viewpoint.'),
('Use the diagram in a customer conversation.','For rental companies, a diagram is a starting point for a quote discussion. Configure supported equipment in your catalog and bring customer plans into your dashboard. Review the design alongside availability, site access and delivery details before accepting a rental order.'),
('Keep a version everyone can refer to.','An individual Event Pass provides 30 days of editing, saving, printing and sharing one design. Use a saved plan for discussion, and communicate changes when the event details move. Software access does not include rental equipment or approval of a tent installation.')]),
('party-rental-software','Visual Planning Software for Party Rental Businesses','Add visual event planning to your party rental workflow. RentSketch combines a branded designer, supported equipment catalog and customer quote requests.','Make party rentals<br>easier to picture.','A visual planning workspace for the conversation between your customer and your rental business.',[
('Solve the layout questions earlier.','Customers often know the occasion and guest count before they know the equipment. A visual layout lets you discuss how dining, dancing and service areas will work together. RentSketch focuses on those layout conversations so a quote can begin with a clearer picture.'),
('Connect the design to your catalog.','Add the names, dimensions and prices of the equipment you rent. Supported visual mappings make items recognizable in the designer. Check the catalog during your trial; not every unusual rental item automatically has a custom 3D model.'),
('Use your website as the starting point.','Configure your branding and add the approved website domain in the Install screen. An embed brings the designer into your existing site, while a direct designer link gives you another way to share it. Preview the customer experience before you publish it.'),
('Keep the rental decisions in your workflow.','RentSketch supplies layouts and quote requests. It does not promise automatic inventory availability, dispatch scheduling or a connection to every booking system. Confirm stock, delivery, installation and final rental terms through your existing process.'),
('Evaluate it with a real planning scenario.','Use the 14-day business trial to configure several common products, build a representative event and review a quote request. Compare the customer view with the information your team needs. No credit card is required, and choosing a trial plan does not charge you automatically.')]),
('event-rental-software','Event Rental Planning & Quote Workflow Software | RentSketch','Bring event layouts into your rental quote workflow. Manage supported products, branded customer designs and quote requests with RentSketch.','Bring the layout<br>into the rental conversation.','Keep the visual plan connected to the equipment your team needs to discuss.',[
('Give the customer a common reference.','A list of equipment does not always explain how an event will feel. A drawing adds context: where guests sit, where service happens and how the central space is used. RentSketch turns the conversation into a plan the customer can explore.'),
('Create your business workspace.','Start a trial, add your products and configure your branding. Each product can carry dimensions, pricing and a supported visual mapping. The business dashboard brings customer designs and quote requests into the same workspace.'),
('Install the customer experience.','You can embed your designer on your existing rental website after configuring its allowed domain, or share a direct link. Review the customer journey yourself: opening the designer, selecting equipment and submitting a request should match how your business discusses an event.'),
('Treat quote requests as requests.','A submitted design does not guarantee availability or make a final booking. Review the plan, confirm inventory and check the event location before agreeing on the rental. Deposit and integration workflows require their own setup; they are not automatically connected to every rental platform.'),
('Check fit before you subscribe.','The trial lasts 14 days and does not require a card. Use that time to compare the supported visuals and workflow with the equipment and process you use. When you are ready, open Billing and review the plan and interval in Stripe before paying.')]),
('event-layout-software','Event Floor Plan Software | 2D & 3D Layouts | RentSketch','Create event floor plans with tents, seating and rental equipment. Explore 2D and 3D layouts for weddings, parties and rental quote conversations.','An event floor plan<br>people can picture.','Start with the space. Add the equipment. See how the event comes together.',[
('Define the event before arranging the tables.','List the guest count and the activities you need to accommodate. A seated meal, dancing, a buffet and a presentation use space in different ways. Identify those areas first so the drawing represents the whole event rather than only the dining tables.'),
('Build from a measured footprint.','Choose the tent or planning area and verify its dimensions. Add furniture with the sizes you intend to rent. Keep permanent obstacles and routes in the discussion. A plan is most useful when the equipment and space match the actual event conditions.'),
('Use two views for different questions.','In 2D, compare placement and look at the arrangement from above. In 3D, explore perspective and help others understand the setup. RentSketch uses the same event for both views, so you do not need to redraw the design to explain another viewpoint.'),
('Choose access for the job.','Individual event planners can preview the designer for five minutes and purchase a $9.99 Event Pass for 30 days of access to one design. Rental companies use a separate business workspace with a catalog, branding and customer quote workflow.'),
('Review the plan with the people setting up.','Use the plan to ask specific questions about the equipment, entrances, service areas and installation. Confirm availability and site suitability with the venue and rental team. The software is a visual planning tool, not an engineering approval or equipment reservation.')]),
('wedding-layout-planner','Wedding Reception Layout Planner | 2D & 3D | RentSketch','Plan a wedding reception layout with tables, chairs, a tent and a dance floor. Preview the arrangement in 2D and 3D and share a clearer event plan.','Picture the reception.<br>Plan the details.','Bring tables, dancing and gathering spaces into one wedding layout.',[
('Start with the moments you are planning for.','Think about dinner, speeches, dancing and how guests arrive. Decide whether the ceremony shares the same space or uses a separate area. Those decisions determine what the reception layout needs to accommodate before you choose individual table positions.'),
('Place the large areas first.','Begin with the tent or reception footprint. Add the dance floor, head table and service areas, then work through the guest tables. Make room for the equipment that is easy to overlook, such as a DJ area or a buffet table.'),
('Review table shapes and the guest count together.','Round and banquet tables produce different arrangements. Choose the tables and chair counts that match the intended rental, and leave the space between them visible. The venue and rental team should review the plan against the real site and event requirements.'),
('Share the picture, not only a list.','RentSketch lets you compare an overhead layout with a 3D view of the same event. Use the picture to discuss changes with the people helping you plan. The sample reception on our demo page gives you a way to explore the views before buying access.'),
('Choose a one-time Event Pass for your wedding.','A $9.99 Event Pass covers one design for 30 days of editing, saving, printing and sharing. A five-minute preview is free. If you need longer, an optional $4.99 renewal adds 30 days to the same event. This is software access; your rental equipment and venue are booked separately.')])
]
for slug,title,desc,heading,intro,sections in articles:
    body='<section class="page-hero"><div class="wrap"><div class="eyebrow">RentSketch planning resources</div><h1>'+heading+'</h1><p>'+intro+'</p><div class="actions"><a class="btn primary" href="/demo/">Explore a layout ↗</a><a class="btn" href="/business/pricing.html">See pricing</a></div></div></section><section class="section"><div class="wrap guide"><article>'
    body+=''.join('<h2>'+h+'</h2><p>'+p+'</p>' for h,p in sections)
    body+='</article><aside class="guide-aside"><h3>See it in a real layout.</h3><p>Explore an example with tables, chairs and a dance floor. Switch between the plan and the 3D view.</p><a class="btn primary" href="/demo/">Open the demo ↗</a><a href="/business/">For rental businesses →</a><a href="/business/pricing.html#event-pass">Planning your own event →</a><a href="/help/">Help &amp; getting started →</a></aside></div></section>'+cta()
    page(slug+'/index.html',title,desc,body)

page('help/index.html','Getting Started & Purchase Help | RentSketch','Set up your rental business workspace, understand the trial, manage subscriptions and recover a purchased Event Pass. RentSketch customer help.', '''<section class="page-hero"><div class="wrap"><div class="eyebrow">RentSketch help</div><h1>Your next step,<br>made clear.</h1><p>Set up your workspace or get back to the event you purchased.</p></div></section><section class="section"><div class="wrap guide"><article><h2 id="business">Set up a business workspace</h2><ol><li><a href="/business/signup.html">Create a 14-day trial</a>. No credit card is required.</li><li>Open <strong>Products</strong> and add the equipment you want customers to use. Set names, dimensions, prices and supported visual models.</li><li>Open <strong>Branding</strong> and configure your business identity.</li><li>Open <strong>Install</strong>, preview your designer, and add your website’s domain before embedding.</li><li>Review your own customer journey before publishing. Submitted quote requests appear in <strong>Requests</strong>.</li></ol><h2>Choose a paid business subscription</h2><p>In your dashboard, open Billing, choose a plan and select monthly or yearly billing. Stripe Checkout displays the payment details before you subscribe. Your trial does not charge you automatically.</p><p>If you already have a subscription, use Manage Billing in Stripe to manage it. Returning from Checkout alone does not confirm payment; the dashboard reads the saved subscription status.</p><h2>Purchase an individual Event Pass</h2><p>Open the designer for a five-minute preview. When you choose to unlock the event, review the $9.99 price for 30 days of access, provide your email and continue to Stripe. The current draft is saved before checkout.</p><p>After verified payment, you return to the event and receive a private access link by email. Keep the link private. Equipment rentals are a separate purchase.</p><h2>Find an event you already paid for</h2><p>Use your purchase email’s private link, or visit <a href="/my-event/">Open my saved event</a> and request the access email again. Check the spelling of the email address and your spam folder. A pending payment or a canceled checkout does not activate a pass.</p><h2>Get help with a purchase</h2><p>Email <a href="mailto:hello@rentsketch.com">hello@rentsketch.com</a> with the account email, approximate purchase date and what went wrong. Do not send passwords or full card details.</p></article><aside class="guide-aside"><h3>Quick links</h3><a href="/dashboard/">Business dashboard →</a><a href="/my-event/">Open my saved event →</a><a href="/business/pricing.html">Pricing →</a><a href="/demo/">Explore the demo →</a></aside></div></section>''')

page('privacy/index.html','Privacy Notice | RentSketch','Learn how RentSketch uses account information, event designs and payment references to operate its event planning software.', '''<section class="page-hero"><div class="wrap"><h1>Privacy at RentSketch.</h1><p>Information used to provide the event design service.</p></div></section><section class="section"><div class="wrap guide"><article><h2>Account and event information</h2><p>RentSketch stores business account information, including the business name, email address and a hashed password. The service also stores event designs and the information submitted with quote requests so users and the relevant rental business can work with those plans.</p><h2>Payments and access</h2><p>Stripe hosts checkout and handles payment information. RentSketch stores payment references, payment status, the purchase email and access periods to provide subscriptions or Event Pass access. Private event links are used to reopen a purchased design.</p><h2>Browser storage</h2><p>The designer uses browser storage for draft and session information. The business dashboard stores a sign-in token so the account can remain signed in. Signing out clears the dashboard token; clearing browser storage can remove local drafts and preview state.</p><h2>Service providers and rental businesses</h2><p>Hosting, payment and email services process information needed to operate RentSketch. When you use a rental company’s designer and submit an event or quote request, that business receives the relevant information. Its handling of rental orders is separate from RentSketch software access.</p><h2>Questions and requests</h2><p>Contact <a href="mailto:hello@rentsketch.com">hello@rentsketch.com</a> with privacy, account or data requests. Include enough information to identify your account, but never send a password, full payment card number or private event access link.</p></article></div></section>''')

page('404.html','Page Not Found | RentSketch','Find your way back to RentSketch event design software.', '''<div class="error-panel"><div class="eyebrow">404 · Page not found</div><h1>Let’s get you back<br>to the plan.</h1><p>This address does not match a RentSketch page.</p><div class="actions" style="justify-content:center"><a class="btn primary" href="/">Go to RentSketch</a><a class="btn" href="/my-event/">Open my saved event</a></div></div>''',noindex=True)

# Static SVG uses the same dimensions and furniture positions as the 3D example.
svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 480"><defs><pattern id="grid" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M12 0H0V12" fill="none" stroke="#dce5d7" stroke-width=".6"/></pattern><pattern id="wood" width="24" height="24" patternUnits="userSpaceOnUse"><rect width="24" height="24" fill="#d8b78b"/><path d="M0 12H24M12 0V24" stroke="#ba9767" stroke-width=".6"/></pattern></defs><rect width="720" height="480" fill="#edf3e7"/><rect width="720" height="480" fill="url(#grid)"/><path d="M120 58H600M120 52V64M600 52V64M95 80V400M89 80H101M89 400H101" fill="none" stroke="#9aac8c"/><g font-family="system-ui,sans-serif" font-size="11" fill="#6c8060"><text x="345" y="48">60 ft</text><text x="69" y="246" transform="rotate(-90 69 246)">40 ft</text></g><rect x="120" y="80" width="480" height="320" rx="2" fill="#fffdf6" stroke="#7c9670" stroke-width="2"/>']
for x in [120,200,280,360,440,520,600]:
    for y in [80,400]:svg.append(f'<circle cx="{x}" cy="{y}" r="3" fill="#638057"/>')
for cx,cy in [(x,y) for x in [8,22,38,52] for y in [10,30]]:
    px,py=120+cx*8,80+cy*8
    for n in range(8):
        a=n*math.pi/4
        qx,qy=px+29*math.cos(a),py+29*math.sin(a)
        svg.append(f'<rect x="{qx-5:.1f}" y="{qy-4:.1f}" width="10" height="8" rx="2" fill="#e7eddf" stroke="#9fac93" stroke-width=".9" transform="rotate({n*45+90} {qx:.1f} {qy:.1f})"/>')
    svg.append(f'<ellipse cx="{px:.1f}" cy="{py:.1f}" rx="20" ry="20" fill="#faf8ef" stroke="#b5b69c" stroke-width="1.4"/><circle cx="{px:.1f}" cy="{py:.1f}" r="4" fill="#8b9d70"/>')
svg.append('<rect x="312" y="192" width="96" height="96" fill="url(#wood)" stroke="#a17d54" stroke-width="1.3"/><rect x="310" y="226" width="100" height="27" rx="4" fill="#fffdf5e8"/><text x="360" y="244" text-anchor="middle" font-family="system-ui,sans-serif" font-size="10" fill="#7a6244">12′ × 12′ dance floor</text><circle cx="280" cy="240" r="4" fill="#63765a"/><circle cx="440" cy="240" r="4" fill="#63765a"/><text x="360" y="436" text-anchor="middle" font-family="system-ui,sans-serif" font-size="10" fill="#7d8c71">Example arrangement · review clearances with your rental team</text></svg>')
save('assets/example-layout.svg',''.join(svg))
save('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('  <url><loc>'+URL+p+'</loc></url>\n' for p in PAGES)+'</urlset>')
print('Built',len(PAGES),'indexable public pages and signup/404 pages.')
